56	unsigned long Jaccard::getTotalIntersection(RecordKeyVector &hits)
57	{
58		unsigned long intersection = 0;
59		Record *key = hits.getKey();
60		CHRPOS keyStart = key->getStartPos();
61		CHRPOS keyEnd = key->getEndPos();
62	
63		int hitIdx = 0;
64		for (RecordKeyVector::iterator_type iter = hits.begin(); iter != hits.end(); iter = hits.next()) {
65			Record *currRec = *iter;
66			CHRPOS maxStart = max(currRec->getStartPos(), keyStart);
67			CHRPOS minEnd = min(currRec->getEndPos(), keyEnd);
68			if (_context->getObeySplits()) {
69				intersection += upCast(_context)->getSplitBlockInfo()->getOverlapBases(hitIdx);
70				hitIdx++;
71			} else {
72				intersection += (unsigned long)(minEnd - maxStart);
73			}
74		}
75		_numIntersections += (int)hits.size();
76		return intersection;
77	}
