38	bool NewChromSweep::init() {
39	
40	    //Create new FileRecordMgrs for the input files.
41	    //Open them, and get the first record from each.
42	    //otherwise, return true.
43	    _queryFRM = _context->getFile(_context->getQueryFileIdx());
44	
45	    _dbFRMs.resize(_numDBs, NULL);
46	    for (int i=0; i < _numDBs; i++) {
47	        _dbFRMs[i] = _context->getDatabaseFile(i);
48	    }
49	
50	    _currDbRecs.resize(_numDBs, NULL);
51	    if (!_context->hasGenomeFile()) 
52	    {
53	        _fileTracks.resize(_numFiles, NULL);
54	        for (int i=0; i < _numFiles; i++) 
55	        {
56	            _fileTracks[i] = new _orderTrackType;
57	        }
58	    }
59	
60	    for (int i=0; i < _numDBs; i++) {
61	        nextRecord(false, i);
62	        testChromOrder(_currDbRecs[i]);
63	    }
64	
65	    _caches.resize(_numDBs);
66	    _wasInitialized = true;
67	    return true;
68	 }
