70	void NewChromSweep::closeOut(bool testChromOrderVal) {
71	    if (_testLastQueryRec) {
72	        testChromOrder(_currQueryRec);
73	    }
74	    bool should_test_last_rec = true;
75	    while (!_queryFRM->eof()) {
76	        nextRecord(true);
77	        testChromOrder(_currQueryRec);
78	        _queryFRM->deleteRecord(_currQueryRec);
79			should_test_last_rec = false;
80	    }
81	    if (testChromOrderVal) {
82	        if(should_test_last_rec) testChromOrder(_currQueryRec);
83	        for (int i=0; i < _numDBs; i++) {
84	            while (!_dbFRMs[i]->eof()) {
85	                if (testChromOrderVal) testChromOrder(_currDbRecs[i]);
86	                _dbFRMs[i]->deleteRecord(_currDbRecs[i]);
87	                nextRecord(false, i);
88	            }
89	            if (testChromOrderVal) testChromOrder(_currDbRecs[i]);
90	        }
91	    }
92	}
