94	NewChromSweep::~NewChromSweep(void) {
95	    if (!_wasInitialized) {
96	        return;
97	    }
98	    testThatAllDbChromsExistInQuery();
99	
100	    _queryFRM->deleteRecord(_currQueryRec);
101	    _currQueryRec = NULL;
102	
103	
104	    for (int i=0; i < _numDBs; i++) {
105	        _dbFRMs[i]->deleteRecord(_currDbRecs[i]);
106	        _currDbRecs[i] = NULL;
107	    }
108	
109	    _queryFRM->close();
110	
111	   for (int i=0; i < _numDBs; i++) {
112	       _dbFRMs[i]->close();
113	   }
114	
115	   for(int i = 0; i < _numFiles; i ++) {
116		   free(_filePrevChrom[i]);
117	   }
118	
119	    if (!_context->hasGenomeFile()) {
120	        for (int i=0; i < _numFiles; i++) {
121	            delete _fileTracks[i];
122	        }
123	    }
124	}
