336	void NewChromSweep::testChromOrder(const Record *rec)
337	{
338	    // Only use this method if we don't have a genome file
339	    // and the record is valid
340	    if (_context->hasGenomeFile() || rec == NULL) return;
341	
342	    int fileIdx = rec->getFileIdx();
343	
344	    const string &chrom = rec->getChrName();
345	
346	    findChromOrder(rec);
347	
348	    //determine what the previous chrom was for this file.
349	
350		if (_filePrevChrom[fileIdx] == NULL) {
351			_filePrevChrom[fileIdx] = strdup(chrom.c_str());
352			return;
353		}
354	
355		if (strcmp(_filePrevChrom[fileIdx], chrom.c_str()) == 0) return;
356	
357		const string prevChrom(_filePrevChrom[fileIdx]);
358	
359		free(_filePrevChrom[fileIdx]);
360		_filePrevChrom[fileIdx] = strdup(chrom.c_str());
361	
362	
363	    if (verifyChromOrderMismatch(chrom, prevChrom, fileIdx)) {
364	        fprintf(stderr, "ERROR: chromomsome sort ordering for file %s is inconsistent with other files. Record was:\n", _context->getInputFileName(fileIdx).c_str());
365	        rec->print(stderr, true);
366	        exit(1);
367	    }
368	
369	    if (!_lexicoDisproven && chrom < prevChrom) {
370	        if (_lexicoAssumed) {
371	            // ERROR.
372	            fprintf(stderr, "ERROR: Sort order was unspecified, and file %s is not sorted lexicographically.\n",
373	                    _context->getInputFileName(fileIdx).c_str());
374	            fprintf(stderr, "       Please rerun with the -g option for a genome file.\n       See documentation for details.\n");
375	            exit(1);
376	        }
377	        _lexicoDisproven = true;
378	    }
379	}
380	
381	bool NewChromSweep::queryChromAfterDbRec(const Record *dbRec)
382	{
383	    //If using a genome file, compare chrom ids.
384	    //Otherwise, compare global order, inserting as needed.
385	    if (_context->hasGenomeFile()) {
386	        return (_currQueryRec->getChromId() > dbRec->getChromId()) ;
387	    }
388	    //see if query has both
389	    const string &qChrom = _currQueryRec->getChrName();
390	    const string &dbChrom = dbRec->getChrName();
391	    const _orderTrackType *track = _fileTracks[_currQueryRec->getFileIdx()];
392	    _orderTrackType::const_iterator iter = track->find(qChrom);
393	
394	
395	    int qOrder = iter->second;
396	    iter = track->find(dbChrom);
397	    if (iter == track->end()) {
398	        //query file does not contain the dbChrom.
399	        //try a lexicographical comparison, if possible.
400	        return testLexicoQueryAfterDb(_currQueryRec, dbRec);
401	    }
402	    int dbOrder = iter->second;
403	
404	    return (qOrder > dbOrder);
405	}
406	
407	
408	int NewChromSweep::findChromOrder(const Record *rec) {
409	    const string &chrom = rec->getChrName();
410	    int fileIdx = rec->getFileIdx();
411	    _orderTrackType *track = _fileTracks[fileIdx];
412	
413	    _orderTrackType::const_iterator iter = track->find(chrom);
414	    if (iter == track->end()) {
415	        //chrom never seen before. Enter into map.
416	        int val = (int)track->size();
417	        track->insert(pair<string, int>(chrom, val));
418	        return val;
419	    } else {
420	        return iter->second;
421	    }
422	}
423	
424	bool NewChromSweep::verifyChromOrderMismatch(const string & chrom, const string &prevChrom, int skipFile) {
425	    //for every file except the one being checked,
426	    //find the current and previous chrom. If a given file
427	    //is missing either, skip it and go on. If it has both,
428	    //and the curr has a lower order num than the prev, return true.
429	
430	    //if that never happens, return false.
431	    for (int i=0; i < _numFiles; i++) {
432	        if (i == skipFile) continue;
433	        const _orderTrackType *track = _fileTracks[i];
434	        _orderTrackType::const_iterator iter = track->find(chrom);
435	        if (iter == track->end()) continue; //this file does not contain the curr chrom
436	        int currOrder = iter->second;
437	        iter = track->find(prevChrom);
438	        if (iter == track->end()) continue; //this file does not contain the prevChrom.
439	        int prevOrder = iter->second;
440	
441	        if (currOrder < prevOrder) return true;
442	    }
443	    return false;
444	}
445	
446	void NewChromSweep::testThatAllDbChromsExistInQuery()
447	{
448	    if (_context->hasGenomeFile() || !_lexicoDisproven) return;
449	
450	    int queryIdx = _context->getQueryFileIdx();
451	    //get the query file track. Then check that every chrom in every db exists in it.
452	    const _orderTrackType *qTrack = _fileTracks[queryIdx];
453	
454	    for (int i=0; i < _numFiles; i++) {
455	        if (i == queryIdx) continue;
456	        const _orderTrackType *dbTrack = _fileTracks[i];
457	        for (_orderTrackType::const_iterator iter = dbTrack->begin(); iter != dbTrack->end(); iter++) {
458	            const string &chrom = iter->first;
459	            if (qTrack->find(chrom) == qTrack->end()
460	                && !chrom.empty())  // don't raise an error if the chrom is unknown (e.g., unmapped BAM)
461	            {
462	                fprintf(stderr, "ERROR: Database file %s contains chromosome %s, but the query file does not.\n",
463	                        _context->getInputFileName(i).c_str(), chrom.c_str());
464	                fprintf(stderr, "       Please rerun with the -g option for a genome file.\n       See documentation for details.\n");
465	                exit(1);
466	            }
467	        }
468	    }
469	}
470	
471	
472	bool NewChromSweep::testLexicoQueryAfterDb(const Record *queryRec, const Record *dbRec)
473	{
474	    if (_lexicoDisproven) return false;
475	
476	    bool queryGreater = queryRec->getChrName() > dbRec->getChrName();
477	    if (!_lexicoAssumed && queryGreater) {
478	        _lexicoAssumed = true;
479	        _lexicoAssumedFileIdx = dbRec->getFileIdx();
480	        _lexicoAssumedChromName = dbRec->getChrName();
481	    }
482	    return queryGreater;
483	}

